const encontradas = $input.all().map(i => i.json).filter(row => row && row.id);
if (encontradas.length === 0) return [{ json: { encontrada: false } }];
return [{ json: { encontrada: true, empresa_id: encontradas[0].id } }];

// ---- Grade padrão por dia da semana (0=Domingo ... 6=Sábado) ----
// Edite aqui se a empresa mudar o horário de funcionamento.
const gradePorDia = {
  0: [],
  1: ["09:00","10:00","11:00","13:00","14:00","15:00","16:00","17:00"],
  2: ["09:00","10:00","11:00","13:00","14:00","15:00","16:00","17:00"],
  3: ["09:00","10:00","11:00","13:00","14:00","15:00","16:00","17:00"],
  4: ["09:00","10:00","11:00","13:00","14:00","15:00","16:00","17:00"],
  5: ["09:00","10:00","11:00","13:00","14:00","15:00","16:00","17:00"],
  6: ["09:00","10:00","11:00","13:00","14:00"],
};

const query = $('Webhook').first().json.query || {};
const dataFiltro = query.data;
const duracaoSolicitada = Number(query.duracao) || 30;
const colaboradorFiltro = query.colaborador;

if (!dataFiltro) {
  return [{ json: { erro: 'Parametro "data" (AAAA-MM-DD) e obrigatorio.' } }];
}
if (!colaboradorFiltro) {
  return [{ json: { erro: 'Parametro "colaborador" e obrigatorio.' } }];
}

const [ano, mes, dia] = dataFiltro.split('-').map(Number);
const diaSemana = new Date(ano, mes - 1, dia).getDay();
const gradePadrao = gradePorDia[diaSemana] || [];

const toMinutos = (hhmm) => {
  const [h, m] = hhmm.split(':').map(Number);
  return h * 60 + m;
};

// Ja vem filtrado por colaborador+empresa direto na query ao Supabase; aqui filtra data+status
const ocupados = $('Ler Agendamentos (Supabase)').all()
  .map(item => item.json)
  .filter(row => row && row.hora && row.data === dataFiltro && row.status !== 'Cancelado')
  .map(row => {
    const inicio = toMinutos(row.hora);
    const duracao = Number(row.duracao_minutos) || 30;
    return { inicio, fim: inicio + duracao };
  });

// Ja vem filtrado por colaborador+empresa direto na query ao Supabase; aqui filtra data+status
const bloqueios = $('Ler Bloqueios (Supabase)').all()
  .map(item => item.json)
  .filter(row => row && row.data === dataFiltro && row.status === 'Ativo');

const bloqueioDiaInteiro = bloqueios.some(b => !b.hora_inicio && !b.hora_fim);

const bloqueiosParciais = bloqueios
  .filter(b => b.hora_inicio && b.hora_fim)
  .map(b => ({ inicio: toMinutos(b.hora_inicio), fim: toMinutos(b.hora_fim) }));

// O sandbox do Code node do n8n roda sempre em UTC, ignorando TZ/GENERIC_TIMEZONE do container.
// America/Sao_Paulo = UTC-3 fixo (sem horario de verao desde 2019), entao a conversao e manual aqui.
const agoraSP = new Date(Date.now() - 3 * 60 * 60 * 1000);
const ehHoje = agoraSP.getUTCFullYear() === ano && (agoraSP.getUTCMonth() + 1) === mes && agoraSP.getUTCDate() === dia;
const minutosAgora = agoraSP.getUTCHours() * 60 + agoraSP.getUTCMinutes();

// Fecha o expediente 60min apos o ultimo horario da grade (aprox. p/ evitar estourar o fim do dia)
const fechamento = gradePadrao.length ? toMinutos(gradePadrao[gradePadrao.length - 1]) + 60 : 0;

const horariosLivres = bloqueioDiaInteiro ? [] : gradePadrao.filter(hora => {
  const inicioSlot = toMinutos(hora);
  const fimSlot = inicioSlot + duracaoSolicitada;

  if (fimSlot > fechamento) return false;
  if (ehHoje && inicioSlot <= minutosAgora) return false;

  const temConflito = ocupados.some(o => o.inicio < fimSlot && o.fim > inicioSlot);
  if (temConflito) return false;

  const temBloqueio = bloqueiosParciais.some(b => b.inicio < fimSlot && b.fim > inicioSlot);
  return !temBloqueio;
});

return [{
  json: {
    data: dataFiltro,
    colaborador: colaboradorFiltro,
    duracao_minutos: duracaoSolicitada,
    horarios_disponiveis: horariosLivres
  }
}];
